def _recovery_tokenize(self, tokens):
    for token in tokens:
        typ = token[0]
        if typ == DEDENT:
            # We need to count indents, because if we just omit any DEDENT,
            # we might omit them in the wrong place.
            o = self._omit_dedent_list
